begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.login(i integer) returns void language plpgsql as $$ begin
 perform set_config('role','authenticated',true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub','42100000-0000-4000-8000-'||lpad(i::text,12,'0'),'role','authenticated')::text,true);
end $$;
insert into auth.users(instance_id,id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at,confirmation_token,email_change,email_change_token_new,recovery_token)
select '00000000-0000-0000-0000-000000000000',('42100000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'authenticated','authenticated','calendar-test-'||i||'@example.test','{}','{}',now(),now(),'','','','' from generate_series(1,6) i;
select pg_temp.login(1);
create temp table ctx as select public.create_project('Calendar fixture','Pacific/Kiritimati','GBP','2026-01-01') id;
create temp table cat as with c as(insert into public.project_areas(project_id,title) select id,'Calendar category' from ctx returning id) select * from c;
create temp table activity as select (public.create_activity_in_category((select id from ctx),(select id from cat),'{"title":"Timed","kind":"other","activity_type":"event","estimated_cost_minor":1000,"starts_at":"2026-10-07T23:30:00Z","is_all_day":false}',null)).id;
create temp table allday as select (public.create_activity_in_category((select id from ctx),(select id from cat),'{"title":"All day","kind":"other","activity_type":"task","starts_at":"2026-10-07T10:00:00Z","is_all_day":true}',null)).id;
create temp table series as select (public.create_activity_in_category((select id from ctx),(select id from cat),'{"title":"Weekly","kind":"other","activity_type":"task","starts_at":"2026-10-07T10:00:00Z","recurrence_frequency":"weekly","recurrence_interval":1,"recurrence_start_date":"2026-10-08","recurrence_active":true}',null)).id;
create temp table decision as select public.create_decision((select id from ctx),'Choose',null,null,'[{"title":"A"},{"title":"B"}]') id;
create temp table schedule as with s as(insert into public.activity_payment_schedules(project_id,commitment_id,title,amount_minor,due_on) select ctx.id,activity.id,'Deposit',1000,'2026-10-08' from ctx,activity returning id) select * from s;
insert into public.payments(project_id,commitment_id,payment_schedule_id,type,status,amount_minor,due_on) select ctx.id,activity.id,schedule.id,'deposit','scheduled',1000,'2026-10-08' from ctx,activity,schedule;
set local role postgres;
update public.decisions set voting_deadline='2026-10-07T23:30:00Z' where id=(select id from decision);
insert into public.project_members(project_id,user_id,display_name,role,status)
select ctx.id,('42100000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'Calendar member '||i,case when i=3 then 'viewer' else 'member' end::public.member_role,'active' from ctx,generate_series(2,4) i;
select pg_temp.login(1);
create function pg_temp.entries() returns setof record language sql as $$ select * from public.get_project_calendar((select id from ctx),'2026-10-08','2026-10-09') $$;
create temp view entries as select * from public.get_project_calendar((select id from ctx),'2026-10-08','2026-10-09');
select is((select count(*)::int from entries),5,'All authoritative sources projected once');
select is((select count(distinct entry_id)::int from entries),5,'Stable unique source identities');
select is((select entry_id from entries where source_type='payment_schedule'),'payment_schedule:'||(select id from schedule),'Schedule identity is schedule ID, not Activity ID');
select is((select count(*)::int from entries where source_type='activity' and source_id=(select id from series)),0,'Recurring parent suppressed');
select is((select occurrence_date from entries where source_type='activity_occurrence'),'2026-10-08'::date,'Existing recurrence engine projects local date');
select is((select start_at from entries where source_id=(select id from activity)),'2026-10-07T23:30:00Z'::timestamptz,'Timed Activity preserves timestamp');
select is((select start_date from entries where source_id=(select id from allday)),'2026-10-08'::date,'All-day Activity returns project date');
select ok((select start_at is null and all_day from entries where source_id=(select id from allday)),'All-day Activity has no fake timestamp');
select ok((select start_at is null and all_day and start_date='2026-10-08' from entries where source_type='payment_schedule'),'Schedule stays date-only');
select is((select category_name from entries where source_id=(select id from activity)),'Calendar category','Category joined in one call');
select is((select activity_type from entries where source_id=(select id from activity)),'event','Domain Activity type retained');
select is((select amount_minor from entries where source_type='payment_schedule'),1000::bigint,'Minor units, no SQL formatting');
select is((select currency_code from entries where source_type='payment_schedule'),'GBP','Project currency');
select is((select count(*)::int from public.get_project_calendar((select id from ctx),'2026-10-07','2026-10-08')),0,'Exclusive end and timezone boundary exclude later dates');
select is((select count(*)::int from public.get_project_calendar((select id from ctx),'2026-10-09','2026-10-10')),0,'Earlier dates excluded');
select throws_ok($$select * from public.get_project_calendar((select id from ctx),'2026-10-08','2026-10-08')$$,'22023',null,'Empty range rejected');
select throws_ok($$select * from public.get_project_calendar((select id from ctx),'2026-01-01','2027-01-01')$$,'22023',null,'Unbounded history rejected');
select throws_ok($$select * from public.get_project_calendar((select id from ctx),null,'2026-10-08')$$,'22023',null,'Null range rejected');
select pg_temp.login(2);
select is((select count(*)::int from entries),5,'Member reads sources');
select pg_temp.login(3);
select is((select count(*)::int from entries),5,'Viewer reads authorized sources including schedule');
update public.activity_payment_schedules set title='No' where id=(select id from schedule);
select is((select title from entries where source_type='payment_schedule'),'Deposit','Viewer gains no schedule mutation');
select pg_temp.login(5);
select is((select count(*)::int from entries),0,'Nonmember cannot read');
create temp table other as select public.create_project('Other calendar','UTC','GBP','2026-01-01') id;
select is((select count(*)::int from entries),0,'Other project organizer cannot read');
select pg_temp.login(1);
set local role postgres;
update public.project_members set status='removed' where project_id=(select id from ctx) and user_id='42100000-0000-4000-8000-000000000004';
select pg_temp.login(4);
select is((select count(*)::int from entries),0,'Removed member cannot read');
select pg_temp.login(1);
create temp table token as select public.regenerate_project_join_link((select id from ctx)) value;
select pg_temp.login(6);
select public.request_project_access((select value from token));
select is((select count(*)::int from entries),0,'Requester has no calendar access');
select pg_temp.login(1);
insert into public.payments(project_id,commitment_id,payment_schedule_id,paid_by_member_id,type,direction,status,amount_minor,paid_on) select ctx.id,activity.id,schedule.id,(select id from public.project_members where project_id=ctx.id and user_id=auth.uid()),'deposit','outgoing','paid',400,current_date from ctx,activity,schedule;
select is((select status from entries where source_type='payment_schedule'),'part_paid','Part paid from ledger');
insert into public.payments(project_id,commitment_id,payment_schedule_id,paid_by_member_id,type,direction,status,amount_minor,paid_on) select ctx.id,activity.id,schedule.id,(select id from public.project_members where project_id=ctx.id and user_id=auth.uid()),'balance','outgoing','paid',600,current_date from ctx,activity,schedule;
select is((select status from entries where source_type='payment_schedule'),'paid','Paid history retained');
select public.complete_commitment_occurrence((select id from series),'2026-10-08');
select is((select status from entries where source_type='activity_occurrence'),'completed','Occurrence state projected');
update public.commitments set status='completed' where id=(select id from allday);
select is((select status from entries where source_id=(select id from allday)),'completed','Completed Activity stays visible');
select public.resolve_decision((select id from decision),(select id from public.decision_options where decision_id=(select id from decision) order by sort_order limit 1));
select is((select status from entries where source_type='decision'),'resolved','Resolved deadline stays historical');
update public.commitments set starts_at='2026-10-09T00:00:00Z' where id=(select id from activity);
select is((select count(*)::int from entries where source_type='activity' and source_id=(select id from activity)),0,'Source reschedule removes old date immediately');
select is((select count(*)::int from public.get_project_calendar((select id from ctx),'2026-10-09','2026-10-10') where source_id=(select id from activity)),1,'Source reschedule appears once on new date');
update public.commitments set status='cancelled' where id=(select id from series);
select is((select count(*)::int from entries where source_id=(select id from series)),0,'Cancelled follows Timeline exclusion');
-- Spans and both DST edges use IANA boundaries, never fixed offsets.
update public.commitments set starts_at='2026-10-06T10:00:00Z',ends_at='2026-10-09T10:00:00Z' where id=(select id from activity);
select is((select count(*)::int from entries where source_id=(select id from activity)),1,'Span starting before range is included');
update public.commitments set ends_at='2026-10-07T10:00:00Z' where id=(select id from activity);
select is((select count(*)::int from entries where source_id=(select id from activity)),0,'Timed end at lower boundary excluded');
update public.projects set timezone='Europe/London' where id=(select id from ctx);
update public.commitments set starts_at='2026-03-29T22:30:00Z',ends_at=null where id=(select id from activity);
select is((select count(*)::int from public.get_project_calendar((select id from ctx),'2026-03-29','2026-03-30') where source_id=(select id from activity)),1,'Spring DST 23-hour local day includes 23:30');
update public.commitments set starts_at='2026-03-29T23:00:00Z' where id=(select id from activity);
select is((select count(*)::int from public.get_project_calendar((select id from ctx),'2026-03-29','2026-03-30') where source_id=(select id from activity)),0,'Spring DST next midnight excluded');
update public.commitments set starts_at='2026-10-25T23:30:00Z' where id=(select id from activity);
select is((select count(*)::int from public.get_project_calendar((select id from ctx),'2026-10-25','2026-10-26') where source_id=(select id from activity)),1,'Autumn DST 25-hour day includes 23:30');
update public.projects set timezone='Pacific/Kiritimati' where id=(select id from ctx);
set local role postgres;
create temp table before_read as select
 (select jsonb_agg(to_jsonb(c)) from public.commitments c where project_id=(select id from ctx)) activities,
 (select jsonb_agg(to_jsonb(d)) from public.decisions d where project_id=(select id from ctx)) decisions,
 (select jsonb_agg(to_jsonb(p)) from public.payments p where project_id=(select id from ctx)) payments,
 (select count(*) from app.domain_events where project_id=(select id from ctx)) events,
 (select count(*) from public.notifications where project_id=(select id from ctx)) notifications;
create temp table financial_before as select to_jsonb(f) data from public.v_project_financials f where project_id=(select id from ctx);
create temp table schedules_before as select jsonb_agg(to_jsonb(s) order by s.id) data from public.activity_payment_schedules s where project_id=(select id from ctx);
create temp table shares_before as select jsonb_agg(to_jsonb(s) order by s.id) data from public.cost_shares s where project_id=(select id from ctx);
create temp table balances_before as select jsonb_agg(to_jsonb(s) order by s.member_id) data from public.v_project_member_settlements s where project_id=(select id from ctx);
create temp table reimbursements_before as select jsonb_agg(to_jsonb(s) order by s.id) data from public.reimbursement_requests s where project_id=(select id from ctx);
grant select on before_read to authenticated;
select pg_temp.login(1);
select count(*) from entries;
set local role postgres;
select is((select jsonb_agg(to_jsonb(c)) from public.commitments c where project_id=(select id from ctx)),(select activities from before_read),'Read does not mutate Activities');
select is((select jsonb_agg(to_jsonb(d)) from public.decisions d where project_id=(select id from ctx)),(select decisions from before_read),'Read does not mutate Decisions');
select is((select jsonb_agg(to_jsonb(p)) from public.payments p where project_id=(select id from ctx)),(select payments from before_read),'Read does not mutate payments');
select is((select count(*) from app.domain_events where project_id=(select id from ctx)),(select events from before_read),'Read emits no events');
select is((select count(*) from public.notifications where project_id=(select id from ctx)),(select notifications from before_read),'Read creates no notifications');
select is((select to_jsonb(f) from public.v_project_financials f where project_id=(select id from ctx)),(select data from financial_before),'Read does not change spend');
select is((select jsonb_agg(to_jsonb(s) order by s.id) from public.activity_payment_schedules s where project_id=(select id from ctx)),(select data from schedules_before),'Read does not change schedules');
select is((select jsonb_agg(to_jsonb(s) order by s.id) from public.cost_shares s where project_id=(select id from ctx)),(select data from shares_before),'Read does not change cost shares');
select is((select jsonb_agg(to_jsonb(s) order by s.member_id) from public.v_project_member_settlements s where project_id=(select id from ctx)),(select data from balances_before),'Read does not change balances');
select is((select jsonb_agg(to_jsonb(s) order by s.id) from public.reimbursement_requests s where project_id=(select id from ctx)),(select data from reimbursements_before),'Read does not change reimbursements');
select ok(to_regclass('public.calendar_events') is null,'No duplicate calendar table');
select ok(not (select prosecdef from pg_proc where oid='public.get_project_calendar(uuid,date,date)'::regprocedure),'RPC is security invoker');
select is((select provolatile::text from pg_proc where oid='public.get_project_calendar(uuid,date,date)'::regprocedure),'s','Stable read-only RPC');
select pg_temp.login(1);
select public.soft_delete_decision((select id from decision));
select is((select count(*)::int from entries where source_type='decision'),0,'Soft-deleted Decision excluded');
select public.soft_delete_commitment((select id from activity));
select is((select count(*)::int from entries where source_type='payment_schedule'),0,'Deleted Activity hides schedule even with retained payment history');
set local role anon;
select throws_ok($$select * from public.get_project_calendar('00000000-0000-0000-0000-000000000000','2026-10-08','2026-10-09')$$,'42501',null,'Anonymous execute denied');
select pg_temp.login(1);
set local role postgres;
update public.projects set status='archived' where id=(select id from ctx);
select pg_temp.login(1);
select ok((select count(*) from entries)>0,'Archive remains readable');
set local role postgres;
update public.projects set status='active' where id=(select id from ctx);
select public.soft_delete_project((select id from ctx));
select pg_temp.login(1);
select is((select count(*)::int from entries),0,'Deleted project excluded');
select * from finish();
rollback;
